<?php require 'config/config.php'; require_role('customer');$cart=$_SESSION['cart']??[];if(!$cart)redirect('cart.php');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pickup=trim($_POST['pickup_time']??'');$market=(int)($_POST['market_id']??0);if(!$pickup||!$market){flash('danger','Select market and pickup time.');}else{$pdo=db();$pdo->beginTransaction();try{$total=0;$ids=array_keys($cart);$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($in) FOR UPDATE");$s->execute($ids);$products=$s->fetchAll();$order=$pdo->prepare("INSERT INTO orders(customer_id,total_amount,order_status,pickup_market_id,pickup_time,order_date) VALUES(?,?,?,?,?,NOW())");foreach($products as $p){$q=min((int)$cart[$p['id']],(int)$p['stock_quantity']);$total+=$q*$p['price'];}$order->execute([user()['id'],$total,'placed',$market,$pickup]);$oid=(int)$pdo->lastInsertId();foreach($products as $p){$q=min((int)$cart[$p['id']],(int)$p['stock_quantity']);$pdo->prepare("INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)")->execute([$oid,$p['id'],$q,$p['price']]);$pdo->prepare("UPDATE products SET stock_quantity=stock_quantity-? WHERE id=?")->execute([$q,$p['id']]);}$pdo->commit();$_SESSION['cart']=[];flash('success','Pre-order placed successfully. Pay in person at pickup.');redirect('customer.php');}catch(Throwable $e){$pdo->rollBack();flash('danger','Could not place order.');}}}
$markets=db()->query("SELECT * FROM markets ORDER BY market_name")->fetchAll();layout_header('Checkout');?>
<h2>Pickup checkout</h2><div class="alert alert-info">No online payment is used. Payment is settled in person at pickup.</div><form method="post" class="card p-4" style="max-width:700px"><?=csrf_field()?><label>Pickup market</label><select name="market_id" class="form-select mb-3" required><option value="">Select market</option><?php foreach($markets as $m):?><option value="<?=$m['id']?>"><?=e($m['market_name'])?> — <?=e($m['address'])?></option><?php endforeach;?></select><label>Pickup date/time</label><input type="datetime-local" name="pickup_time" class="form-control mb-3" required><button class="btn btn-success">Place pre-order</button></form><?php layout_footer();?>